pub fn spki_sha256_of_key(pem: &str) -> Result<String, String> {
    let key = rcgen::KeyPair::from_pem(pem).map_err(|e| format!("key: {e}"))?;
    Ok(sha256_hex(&key.subject_public_key_info()))
}

